 * Create all OpenCode hooks wired to aide core logic.
 */
export async function createHooks(
  cwd: string,
  worktree: string,
  client: OpenCodeClient,
  pluginRoot?: string,
  options?: { skipInit?: boolean },
): Promise<Hooks> {
  const state: AideState = {
    initialized: false,
    binary: null,
    cwd,
    worktree,
    pluginRoot: pluginRoot || null,
    skipInit: options?.skipInit ?? false,
    sessionState: null,
    memories: null,
    welcomeContext: null,
    initializedSessions: new Set(),
    processedMessageParts: new Set(),
    pendingSkillsContext: null,
    lastUserPrompt: null,
    sessionInfoMap: new Map(),
    client,
    pruningTrackers: new SessionPruningTrackers(cwd),
    contextSessions: new Set(),
  };

  // Run one-time initialization (directories, binary, config)
  initializeAide(state);

  try {
    await client.app.log({
      body: {
        service: "aide",
        level: "info",
        message: `aide hooks init: cwd=${state.cwd} worktree=${state.worktree} pluginRoot=${state.pluginRoot ?? "unknown"} binary=${state.binary ?? "not-found"} skipInit=${state.skipInit}`,
      },
    });
  } catch (err) {
    debug(SOURCE, `Init log failed (non-fatal): ${err}`);
  }

  return {
    event: createEventHandler(state),
    config: createConfigHandler(state),
    "command.execute.before": createCommandHandler(state),
    "tool.execute.before": createToolBeforeHandler(state),
    "tool.execute.after": createToolAfterHandler(state),
    "experimental.session.compacting": createCompactionHandler(state),
    "experimental.chat.system.transform": createSystemTransformHandler(state),
    "permission.ask": createPermissionHandler(state),
    "shell.env": createShellEnvHandler(state),
  };
}

// =============================================================================
// Config handler (register aide commands as OpenCode slash commands)
// =============================================================================

function establishContext(
  state: AideState,
  session: string,
  reason: "startup" | "unknown",
): void {
  if (
    !state.binary ||
    !session ||
    session === "unknown" ||
    state.contextSessions.has(session)
  )
    return;
  if (
    updateContextWindow(
      state.binary,
      state.cwd,
      { host: "opencode", sessionId: session, actorId: session },
      reason,
    )
  )
    state.contextSessions.add(session);
}

function createEventHandler(
  state: AideState,
): (input: { event: OpenCodeEvent }) => Promise<void> {
  const recordUsage = createOpenCodeUsageRecorder();
  return async ({ event }) => {
    switch (event.type) {
      case "session.created":
        establishContext(state, extractSessionId(event), "startup");
        await handleSessionCreated(state, event);
        break;
      case "session.compacted": {
        const session = extractSessionId(event);
        establishContext(state, session, "unknown");
        state.pruningTrackers.complete(session);
        if (state.binary)
          updateContextWindow(
            state.binary,
            state.cwd,
            { host: "opencode", sessionId: session, actorId: session },
            "compact",
          );
        break;
      }
      case "session.idle":
        await handleSessionIdle(state, event);
        break;
      case "session.deleted":
        await handleSessionDeleted(state, event);
        break;
      case "message.part.updated":
        if (state.binary)
          recordUsage(state.binary, state.cwd, event.properties.part);
        await handleMessagePartUpdated(state, event);
        break;
      default:
        // Ignore other events
        break;
    }
  };
}

